def signup(email: str) -> bool:
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    if not local or "." not in domain:
        return False
    # ... create user
    return True

def invite_member(email: str) -> bool:
    # Same rule, restated. Will drift on the next product change.
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    if len(local) < 2 or "." not in domain:
        return False
    # ... send invite
    return True

class EmailPolicy:
    @staticmethod
    def is_acceptable(email: str) -> bool:
        # Single authoritative representation of the product rule.
        if email.count("@") != 1:
            return False
        local, domain = email.split("@")
        return bool(local) and "." in domain and " " not in email

def signup(email: str) -> bool:
    if not EmailPolicy.is_acceptable(email):
        return False
    # ... create user
    return True

def invite_member(email: str) -> bool:
    if not EmailPolicy.is_acceptable(email):
        return False
    # ... send invite
    return True

